  "knowledge": "Continuous Filing Employer",
  "description": "Defines employers with regular, ongoing visa application activity.",
  "definition": "An employer is considered a continuous filer if they submit visa applications in at least 9 months of the year, indicating consistent reliance on foreign worker programs."
}

{
  "id": 41,
  "knowledge": "Visa Filing Window",
  "description": "Categorizes the timing of visa application submissions relative to employment start date.",
  "definition": "The visa filing window represents when applications are submitted relative to the intended employment start date. Applications are categorized as: 'Optimal Window (4-6 Months)' before start date, 'Early Filing' (more than 6 months before), '1-3 Months Before', 'Same Month', or 'After Start Date'. These categories help analyze filing patterns and potential processing challenges. Submission and start dates are tracked as part of the application data."
}

{
  "id": 47,
  "knowledge": "Application Status Categories",
  "description": "Defines the possible status outcomes for visa applications.",
  "definition": "Possible outcomes for a visa application include: Certified (approved), Denied (rejected), Withdrawn (voluntarily withdrawn by applicant), and Certified-Withdrawn (approved but later withdrawn). Application status is tracked as part of the application data."
}

{
  "id": 50,
  "knowledge": "Seasonal Application Pattern",
  "description": "Defines patterns in visa application timing throughout the year.",
  "definition": "Seasonal patterns in visa application submissions include Peak Season (periods with higher submission rates), Off-Peak Season (lower submission rates), and Transition Periods (moderate activity between peaks). Application receipt dates are tracked as part of the application data."
}
